<?php

namespace App\Services;

use App\Exceptions\DomainActionException;
use App\Models\DtrEntry;
use App\Models\Student;
use Illuminate\Database\UniqueConstraintViolationException;
use Illuminate\Support\Carbon;
use Illuminate\Support\Facades\DB;

class DtrService
{
    /**
     * Clock a student in.
     *
     * $clientUuid is the idempotency key generated by the offline queue: a
     * replayed check-in returns the original entry instead of erroring.
     * $timeIn lets an offline replay record when the student actually
     * pressed the button, not when the request finally reached the server.
     * $checkinMethod overrides the derived manual/sync value — the QR scan
     * check-in records 'qr' so HR can see the entry was location-proven.
     */
    public function checkin(Student $student, ?string $clientUuid = null, ?Carbon $timeIn = null, ?string $checkinMethod = null): DtrEntry
    {
        if (! $student->company_id) {
            throw new DomainActionException('no_company', 'You cannot clock in until a company has been assigned to you.', 403);
        }

        if ($student->status !== 'active') {
            throw new DomainActionException('inactive', 'Your OJT status must be active to clock in.', 403);
        }

        return DB::transaction(function () use ($student, $clientUuid, $timeIn, $checkinMethod) {
            if ($clientUuid !== null) {
                $existing = $student->dtrEntries()->where('client_uuid', $clientUuid)->first();

                if ($existing) {
                    return $existing;
                }
            }

            if ($student->dtrEntries()->whereNull('time_out')->exists()) {
                throw new DomainActionException('already_active', 'You already have an active time-in. Please time out first.', 409);
            }

            $timeIn ??= now();

            if ($timeIn->gt(now()->addMinutes(5))) {
                throw new DomainActionException('invalid_time_in', 'Time in cannot be in the future.', 422);
            }

            try {
                return DtrEntry::create([
                    'student_id' => $student->id,
                    'client_uuid' => $clientUuid,
                    'date' => $timeIn->toDateString(),
                    'time_in' => $timeIn,
                    'hours' => 0,
                    'checkin_method' => $checkinMethod ?? ($clientUuid === null ? 'manual' : 'sync'),
                ]);
            } catch (UniqueConstraintViolationException) {
                // A concurrent replay of the same client_uuid won the race;
                // its entry is the correct no-op result.
                return $student->dtrEntries()->where('client_uuid', $clientUuid)->firstOrFail();
            }
        });
    }

    /**
     * Clock a student out.
     *
     * $timeOut is normally now(); the offline sync API passes the timestamp
     * captured on the device so offline shifts keep their real hours.
     */
    public function checkout(Student $student, ?string $clientUuid = null, ?string $taskSummary = null, ?Carbon $timeOut = null): DtrEntry
    {
        return DB::transaction(function () use ($student, $clientUuid, $taskSummary, $timeOut) {
            $entry = $student->dtrEntries()
                ->whereNull('time_out')
                ->latest('time_in')
                ->lockForUpdate()
                ->first();

            if (! $entry) {
                // Nothing open: a replayed checkout whose entry was already
                // closed by an earlier attempt is a successful no-op.
                if ($clientUuid !== null) {
                    $existing = $student->dtrEntries()->where('client_uuid', $clientUuid)->first();

                    if ($existing) {
                        return $existing;
                    }
                }

                throw new DomainActionException('no_active_entry', 'You have no active time-in to time out from.', 409);
            }

            $timeOut ??= now();

            if ($timeOut->gt(now()->addMinutes(5))) {
                throw new DomainActionException('invalid_time_out', 'Time out cannot be in the future.', 422);
            }

            if ($timeOut->lte($entry->time_in)) {
                throw new DomainActionException('invalid_time_out', 'Time out must be after the time in.', 422);
            }

            if ($timeOut->diffInHours($entry->time_in) > 24) {
                throw new DomainActionException('invalid_time_out', 'A single shift cannot exceed 24 hours. Ask your coordinator to fix this entry.', 422);
            }

            $entry->update([
                'client_uuid' => $entry->client_uuid ?? $clientUuid,
                'time_out' => $timeOut,
                'hours' => round(abs($timeOut->diffInSeconds($entry->time_in)) / 3600, 2),
                'task_summary' => $taskSummary ?? $entry->task_summary,
            ]);

            return $entry;
        });
    }
}
